"""Disposable public test fixtures, generated by an independent OpenSSL binding.
Never uses a board, an enrolled card, or any project secret.
"""
from datetime import datetime, timezone
from pathlib import Path
from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec, utils
from cryptography.x509.oid import NameOID

root = Path(__file__).resolve().parent
a = ec.derive_private_key(1, ec.SECP256R1())
b = ec.derive_private_key(2, ec.SECP256R1())
def pub(key):
    return key.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
def name(value):
    return x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, value)])
issuer, subject = name('Disposable test issuer'), name('Disposable test leaf')
def cert(start, end):
    return (x509.CertificateBuilder().subject_name(subject).issuer_name(issuer)
            .public_key(b.public_key()).serial_number(2)
            .not_valid_before(datetime(start, 1, 1, tzinfo=timezone.utc))
            .not_valid_after(datetime(end, 1, 1, tzinfo=timezone.utc))
            .add_extension(x509.BasicConstraints(ca=False, path_length=None), critical=True)
            .sign(a, hashes.SHA256()).public_bytes(serialization.Encoding.DER))
digest = hashes.Hash(hashes.SHA256()); digest.update(b'abc'); digest = digest.finalize()
signature = a.sign(digest, ec.ECDSA(utils.Prehashed(hashes.SHA256())))
r, s = utils.decode_dss_signature(signature)
fixtures = dict(test_pub_a=pub(a), test_pub_b=pub(b), test_digest=digest,
                test_signature_raw=r.to_bytes(32,'big') + s.to_bytes(32,'big'),
                test_signature_der=signature, test_ecdh=a.exchange(ec.ECDH(), b.public_key()),
                test_certificate=cert(2025,2027), test_future_certificate=cert(2028,2029))
with (root/'crypto_fixtures.h').open('w') as out:
    out.write('// Generated disposable test fixtures; see make_crypto_fixtures.py.\n#pragma once\n')
    for key, data in fixtures.items():
        out.write('static const unsigned char '+key+'[] = {'+','.join(f'0x{x:02x}' for x in data)+'};\n')
